{
  "name": "jev-compaction-harnesses",
  "version": "0.1.0",
  "description": "fast-jev-compaction for pi and opencode: prune stale tool calls with Jev instead of summarizing your context away.",
  "type": "module",
  "license": "MIT",
  "author": "Ansh Sonkusare",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Ansh-Sonkusare/jev-compaction-harnesses.git"
  },
  "keywords": [
    "pi-package",
    "opencode-plugin",
    "compaction",
    "context",
    "jev",
    "typesafe"
  ],
  "main": "./opencode/plugin.ts",
  "exports": {
    ".": "./opencode/plugin.ts",
    "./opencode": "./opencode/plugin.ts",
    "./pi": "./pi/index.ts"
  },
  "files": [
    "opencode",
    "pi",
    "src",
    "vendor",
    "LICENSE",
    "NOTICE",
    "README.md"
  ],
  "pi": {
    "extensions": [
      "./pi/index.ts"
    ]
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc -p tsconfig.json",
    "sync-upstream": "sh scripts/sync-upstream.sh"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "@earendil-works/pi-tui": {
      "optional": true
    }
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "0.87.1",
    "@opencode-ai/plugin": "1.18.32",
    "@types/bun": "^1.4.2",
    "typescript": "5",
    "@earendil-works/pi-tui": "0.87.1"
  }
}
